// Example of tuning consistency in a Cassandra client
import com.datastax.oss.driver.api.core.ConsistencyLevel;
import com.datastax.oss.driver.api.core.cql.SimpleStatement;

SimpleStatement statement = SimpleStatement.builder("SELECT * FROM users WHERE id = ?")
    .addPositionalValue(userId)
    .setConsistencyLevel(ConsistencyLevel.QUORUM) // Balancing consistency and availability
    .build();
